using System.Text.Json;using System.Text.Json.Nodes;using PackageFlow.Core;
internal static class NativeMigrationTests {
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static async Task Reject(Func<Task> action){try{await action();}catch{return;}throw new Exception("Unsafe migration accepted");}
 public static async Task Run(string root){
  var user=Path.Combine(root,"migration-user");var source=Path.Combine(root,"legacy-export");var games=Path.Combine(root,"original-games");Directory.CreateDirectory(source);Directory.CreateDirectory(games);Directory.CreateDirectory(Path.Combine(user,"data"));
  var profile=Path.Combine(user,"launcher.json");var raw=JsonSerializer.Serialize(new{Schema=1,Mode="compose",GamesDirectory=games,HostIp="192.168.1.5",Port=3333,PayloadPort=3334,AutoStart=true,TorrentSetupSelected=false,SetupComplete=true,WizardComplete=true,ProtectedTrackerPassword="opaque-user-dpapi",ProtectedProwlarrKey="opaque-prowlarr",ProtectedLauncherKey="opaque-launcher",PsIp="192.168.1.6",ConsoleId="profile-preserved",DockerImage="old-unused-option"});File.WriteAllText(profile,raw);
  var lowerFile=Path.Combine(root,"lower-legacy.json");File.WriteAllText(lowerFile,"{\"mode\":\"compose\",\"wizardComplete\":true,\"torrentSetupSelected\":false,\"protectedTrackerPassword\":\"opaque\"}");var lower=LauncherSettings.Load(lowerFile);Check(lower.LegacyMigrationRequired&&lower.WizardComplete&&!lower.TorrentSetupSelected&&lower.ProtectedTrackerPassword=="opaque","Lowercase legacy fields lost");lower.Save(lowerFile);Check(File.Exists(lowerFile+".pre-native-1.10.15.json"),"Lowercase original not backed up");
  var settings=LauncherSettings.Load(profile);Check(settings.Mode=="native"&&settings.LegacyMigrationRequired&&!settings.TorrentSetupSelected,"Legacy profile started as ordinary native or enabled torrents");Check(settings.GamesDirectory==games&&settings.ProtectedTrackerPassword=="opaque-user-dpapi"&&settings.AutoStart&&settings.ConsoleId=="profile-preserved"&&settings.Port==3333,"Legacy settings lost");Check(File.ReadAllText(profile)==raw,"Read-only load mutated source profile");settings.Save(profile);Check(File.ReadAllText(profile+".pre-native-1.10.15.json")==raw,"Exact legacy backup lost unknown fields");Check(LauncherSettings.Load(profile).LegacyMigrationRequired,"Migration review bypassed after save");
  settings.Mode="compose";try{settings.Validate();throw new Exception("Removed mode accepted");}catch(InvalidOperationException){}settings.Mode="native";
  var config=new JsonObject{["services"]=new JsonObject{["packageflow"]=new JsonObject{["volumes"]=new JsonArray(new JsonObject{["type"]="bind",["source"]=source,["target"]="/app/.data"})}}};var cfg=Path.Combine(user,"data","compose.json");File.WriteAllText(cfg,config.ToJsonString());Check(LegacyDataMigration.Inspect(user).Kind=="bind","Known bind not detected");
  await Reject(()=>LegacyDataMigration.Import(source,user,games,false,default));
  var emptyImport=await LegacyDataMigration.Import(source,user,games,true,default);Check(Directory.Exists(emptyImport)&&Directory.Exists(source),"Explicit empty known bind not handled");
  File.WriteAllText(Path.Combine(source,"console-profiles.json"),"{\"activeId\":\"ps5\",\"consoles\":[{\"id\":\"ps5\",\"ip\":\"192.168.1.6\"}]}");File.WriteAllText(Path.Combine(source,"package-library.json"),"{\"packages\":[{\"id\":\"keep-id\",\"path\":\"/games/sub/game.pkg\",\"libraryRoot\":\"/games\",\"coverPath\":\"/app/.data/covers/game.png\"}]}");File.WriteAllText(Path.Combine(source,"qbittorrent.json"),"{\"downloadPath\":\"/games\",\"remotePath\":\"/downloads\",\"password\":\"preserve-private\",\"baseUrl\":\"http://host.docker.internal:8090\"}");File.WriteAllBytes(Path.Combine(source,"storage-secrets.key"),new byte[32]);
  var original=Directory.GetFiles(source).ToDictionary(p=>p,File.ReadAllBytes);var imported=await LegacyDataMigration.Import(source,user,games,false,default);Check(original.All(p=>File.ReadAllBytes(p.Key).SequenceEqual(p.Value)),"Source export changed");var library=JsonNode.Parse(File.ReadAllText(Path.Combine(imported,"package-library.json")))!;Check(library["packages"]![0]!["id"]!.GetValue<string>()=="keep-id"&&library["packages"]![0]!["path"]!.GetValue<string>()==Path.Combine(games,"sub","game.pkg"),"Native path mapping/id preservation failed");var qb=JsonNode.Parse(File.ReadAllText(Path.Combine(imported,"qbittorrent.json")))!;Check(qb["remotePath"]!.GetValue<string>()=="/downloads"&&qb["password"]!.GetValue<string>()=="preserve-private","External download mapping or credentials lost");Check(File.ReadAllBytes(Path.Combine(imported,"storage-secrets.key")).Length==32,"Vault key not copied");
  File.WriteAllText(Path.Combine(source,"installation-queue.json"),"{\"status\":\"running\",\"items\":[]}");await Reject(()=>LegacyDataMigration.Import(source,user,games,false,default));File.Delete(Path.Combine(source,"installation-queue.json"));
  File.WriteAllText(Path.Combine(source,"package-library.json"),"{\"packages\":[{\"path\":\"/games/../../outside.pkg\"}]}");await Reject(()=>LegacyDataMigration.Import(source,user,games,false,default));
  config["services"]!["packageflow"]!["volumes"]=new JsonArray(new JsonObject{["type"]="volume",["source"]="external-user-volume",["target"]="/app/.data"});File.WriteAllText(cfg,config.ToJsonString());Check(LegacyDataMigration.Inspect(user).Kind=="volume"&&!LegacyDataMigration.Inspect(user).EmptyBindAllowed,"External volume silently replaced with blank local data");var blank=Path.Combine(root,"blank-export");Directory.CreateDirectory(blank);await Reject(()=>LegacyDataMigration.Import(blank,user,games,true,default));Check(File.ReadAllText(cfg)==config.ToJsonString(),"Legacy config mutated");
  var nativeFile=Path.Combine(root,"native-settings.json");var native=new LauncherSettings{GamesDirectory=games,AutoStart=true,TorrentSetupSelected=false,ProtectedTrackerPassword="opaque"};native.Save(nativeFile);var reloaded=LauncherSettings.Load(nativeFile);Check(!reloaded.LegacyMigrationRequired&&reloaded.GamesDirectory==games&&reloaded.ProtectedTrackerPassword=="opaque"&&reloaded.AutoStart&&!reloaded.TorrentSetupSelected,"Native settings changed");
 }
}
